    for i,name in ipairs(order) do local b=CreateFrame("Button",nil,mainFrame); b:SetSize(116,28); b:SetPoint("TOPLEFT",8,-62-(i-1)*32); local bg=b:CreateTexture(nil,"BACKGROUND"); bg:SetAllPoints(); b.bg=bg; local t=b:CreateFontString(nil,"OVERLAY","GameFontHighlightSmall"); t:SetPoint("LEFT",8,0); t:SetText(labels[name]); b.text=t; b:SetScript("OnEnter",function(self) if not self.selected then self.bg:SetColorTexture(0.09,0.09,0.12,0.96) end end); b:SetScript("OnLeave",function(self) if not self.selected then self.bg:SetColorTexture(0.045,0.045,0.055,0.94) end end); b:SetScript("OnClick",function() Select(name) end); buttons[name]=b end
    for _,name in ipairs(order) do local p=CreateFrame("Frame",nil,content); p:SetAllPoints(); p:Hide(); panels[name]=p; local m=C.modules[name]; if m and m.build and not m.built then m.build(p); m.built=true end end
    mainFrame.modulePanels=panels; mainFrame.menuButtons=buttons; mainFrame:Hide(); Select("AutoPromote"); return mainFrame
end
function C.ToggleUI() local f=C.BuildMainFrame(); if f:IsShown() then f:Hide() else f:Show() end end
local function HandleSlash(msg) C.InitDB(); C.ToggleUI() end
SLASH_CCRAIDTOOLS1="/ccrt"; SlashCmdList["CCRAIDTOOLS"]=HandleSlash
